from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()

@app.get("/headers")
def read_headers(my_header: str = Header()):
    return {"my_header": my_header}

@app.get("/model_headers")
def read_model_headers(headers: BaseModel = Header()): # This is not how it works, Header() is for a single param
    return {"headers": headers}

# Correct way to use a model for headers:
class HeaderModel(BaseModel):
    my_header: str

@app.get("/model_headers_correct")
def read_model_headers_correct(headers: HeaderModel = Header()):
    return {"headers": headers}

client = TestClient(app)

def test_header_underscore():
    # Should be rejected (or rather, not found) when convert_underscores=True (default)
    # But since it's a required Header, FastAPI should return 422 if not found.
    # If it's accepted, it will return 200.
    response = client.get("/headers", headers={"my_header": "foo"})
    print(f"Test /headers with my_header: {response.status_code}, {response.json()}")
    assert response.status_code == 422

def test_header_hyphen():
    # Should be accepted
    response = client.get("/headers", headers={"my-header": "foo"})
    print(f"Test /headers with my-header: {response.status_code}, {response.json()}")
    assert response.status_code == 200

def test_model_header_underscore():
    # Should be rejected
    response = client.get("/model_headers_correct", headers={"my_header": "foo"})
    print(f"Test /model_headers_correct with my_header: {response.status_code}, {response.json()}")
    assert response.status_code == 422

def test_model_header_hyphen():
    # Should be accepted
    response = client.get("/model_headers_correct", headers={"my-header": "foo"})
    print(f"Test /model_headers_correct with my-header: {response.status_code}, {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_header_underscore()
        test_header_hyphen()
        test_model_header_underscore()
        test_model_header_hyphen()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed!")
        raise e
